fn close_plan_runtime_decode_scheduling(&self, request_ids: &[RequestId]) -> Option<Instant> {
    if !self.config.runtime.profile_detail.captures_engine_token_timing() {
        return None;
    }
    let mut sequences = self.sequences.write();
    let capture_timing = request_ids.iter().any(|request_id| {
        sequences.get(request_id).is_some_and(SequenceState::captures_engine_token_timing)
    });
    if !capture_timing {
        return None;
    }
    let submitted_at = Instant::now();
    for request_id in request_ids {
        let Some(sequence) = sequences.get_mut(request_id) else {
            continue;
        };
        if sequence.closes_pending_decode_scheduling() {
            sequence.close_decode_scheduling(submitted_at);
        }
    }
    Some(submitted_at)
}

